```go
// bloom.go
package bloom

import (
    "math/bits"
    "sync"
)

// DualBitmap holds the original and overlay bitmaps.
// The active bitmap is always the one returned by Active().
// The overlay remains read‑only once building is complete.
// MergeProgress reports percentage of bits merged.
 type DualBitmap struct {
    mu            sync.RWMutex
    original      []uint64
    overlay       []uint64
    activeOverlay bool // false → original, true → overlay
    mergeProg     uint32 // 0–100
    k             int   // number of hash functions
 }

// NewDualBitmap allocates a bitmap twice the size of the original.
func NewDualBitmap(sizeBits int, k int) *DualBitmap {
    sz := (sizeBits + 63) >> 6
    return &DualBitmap{
        original: make([]uint64, sz),
        overlay:  make([]uint64, sz*2),
        k:        k,
    }
}

// Set sets the k hash destinations in both bitmaps for a single element.
func (db *DualBitmap) Set(hash uint64) {
    db.mu.Lock()
    defer db.mu.Unlock()
    for i := 0; i < db.k; i++ {
        idx := uint(hash>>uint(i*6)) & 0x3F // simple example hash
        db.original[idx/64] |= 1 << (idx % 64)
        db.overlay[(idx*2)/64] |= 1 << ((idx*2) % 64)
    }
}

// Test checks if an element is probably present.
func (db *DualBitmap) Test(hash uint64) bool {
    db.mu.RLock()
    defer db.mu.RUnlock()
    b := db.activeOverlay
    bmap := db.original
    if b {
        bmap = db.overlay
    }
    for i := 0; i < db.k; i++ {
        idx := uint(hash>>uint(i*6)) & 0x3F
        if (bmap[idx/64]&(1<<(idx%64))) == 0 {
            return false
        }
    }
    return true
}

// MergeOldIntoOverlay atomically replaces active bitmap with the merged overlay.
func (db *DualBitmap) MergeOldIntoOverlay() {
    db.mu.Lock()
    defer db.mu.Unlock()
    for i := range db.original {
        db.overlay[i] ^= db.original[i]
    }
    db.original = db.overlay // from now on, overlay is the working bitmap
    db.activeOverlay = true
    db.mergeProg = 100
}

// MergeProgress returns current merge state.
func (db *DualBitmap) MergeProgress() uint32 { return db.mergeProg }
