**Dockerfile** (minimal Go runtime)
```
FROM golang:1.22-alpine AS builder
WORKDIR /app
COPY . .
RUN go build -o ./bloomserv ./cmd/

FROM alpine
COPY --from=builder /app/bloomserv /usr/local/bin/bloomserv
CMD ["/usr/local/bin/bloomserv"]
